// Service worker for one Learning Hub app (generated by tools/build.py; do not edit the copy in dist/).
// Every app on vardhangs.github.io shares one Cache Storage, so this worker only ever deletes caches whose
// names start with its own app id.
const APP_ID = "__APP_ID__";
const CACHE = "__CACHE__";
const ASSETS = __ASSETS__;

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k.startsWith(APP_ID + "-") && k !== CACHE).map((k) => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});

// Network-first: always try the latest; fall back to the cache only when offline.
self.addEventListener("fetch", (e) => {
  if (e.request.method !== "GET") return;
  const url = new URL(e.request.url);
  // Let the browser stream videos directly (range requests); don't cache them.
  if (url.pathname.includes("/videos/") && url.pathname.endsWith(".mp4")) return;
  // Only this app's own files and the pinned KaTeX files; never Firebase traffic.
  const mine = url.origin === self.location.origin && url.pathname.startsWith(new URL("./", self.location).pathname);
  const katex = url.origin === "https://cdn.jsdelivr.net" && url.pathname.startsWith("/npm/katex@");
  if (!mine && !katex) return;
  e.respondWith(
    fetch(e.request)
      .then((res) => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(e.request, copy)).catch(() => {}); }
        return res;
      })
      .catch(() => caches.match(e.request, { ignoreSearch: true }))
  );
});
